begin read only;
set local lock_timeout='2s';
set local statement_timeout='12s';
select jsonb_build_object(
 'serverVersion',version(),
 'readOnly',current_setting('transaction_read_only'),
 'tables',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'forceRls',c.relforcerowsecurity,'acl',c.relacl,'columns',(select jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'notNull',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid),'identity',a.attidentity,'generated',a.attgenerated) order by a.attnum) from pg_attribute a left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped),'constraints',(select jsonb_agg(jsonb_build_object('name',conname,'type',contype,'definition',pg_get_constraintdef(oid,true)) order by conname) from pg_constraint where conrelid=c.oid),'indexes',(select jsonb_agg(indexdef order by indexname) from pg_indexes where schemaname=n.nspname and tablename=c.relname),'policies',(select jsonb_agg(to_jsonb(p) order by policyname) from pg_policies p where schemaname=n.nspname and tablename=c.relname),'triggers',(select jsonb_agg(jsonb_build_object('name',t.tgname,'definition',pg_get_triggerdef(t.oid,true),'routine',t.tgfoid::regprocedure::text,'enabled',t.tgenabled) order by t.tgname) from pg_trigger t where t.tgrelid=c.oid and not t.tgisinternal)) order by n.nspname,c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where c.relkind in ('r','p') and ((n.nspname='public' and c.relname in ('vendor_catalog','vendor_catalog_v2','vendors','pending_receivals','inventory_items','inventory_transactions','jobs','app_users','app_role_capabilities')) or (n.nspname='storage' and c.relname='objects'))),
 'routines',(select jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'owner',pg_get_userbyid(p.proowner),'securityDefiner',p.prosecdef,'configuration',p.proconfig,'acl',p.proacl,'bodyMd5',md5(p.prosrc),'definition',pg_get_functiondef(p.oid)) order by p.proname,p.oid::regprocedure::text) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.prokind='f' and (p.proname in ('save_purchasing_catalog_item','save_purchasing_catalog_item_v2','has_app_capability','require_app_capability','guard_business_write','enforce_business_write_permissions','get_my_app_access','has_proposal_access','prepare_invoice_receival_draft','get_invoice_receival_draft','approve_invoice_receival_draft','execute_invoice_receival_draft','tenops_catalog_save_impl','tenops_catalog_save_v2_impl') or p.proname ~ '(receiv|stock)' or p.oid in(select t.tgfoid from pg_trigger t where t.tgrelid in (to_regclass('public.vendor_catalog'),to_regclass('public.vendor_catalog_v2'),to_regclass('public.vendors'),to_regclass('public.pending_receivals'),to_regclass('public.inventory_items'),to_regclass('public.inventory_transactions')) and not t.tgisinternal))),
 'roleCapabilities',(select jsonb_agg(to_jsonb(r) order by to_jsonb(r)::text) from public.app_role_capabilities r),
 'buckets',(select jsonb_agg(jsonb_build_object('id',id,'public',public,'fileSizeLimit',file_size_limit,'allowedMimeTypes',allowed_mime_types) order by id) from storage.buckets),
 'migrationVersions',(select jsonb_agg(jsonb_build_object('version',version,'name',name) order by version) from supabase_migrations.schema_migrations where version like '20261029%' or version like '20261030%' or name ~ '(inventory|receival|catalog|vendor|rbac|stock)'),
 'newObjectsPresent',(select jsonb_agg(c.relname order by c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and (c.relname like 'invoice_receival_%' or c.relname like 'tenbot_invoice_%'))
) as compatibility;
commit;
